class Solution {
public:
    static bool comp(int a,int b)
    {
        return abs(a)<abs(b);
    }
    bool canReorderDoubled(vector<int>& nums) {
        map<int,int> mp;
        for(auto it:nums)
            mp[it]+=1;
        sort(nums.begin(),nums.end(),comp);
        for(auto it:nums)
        {
            if(mp[it]==0)
                continue;
            if(mp[it*2]==0)
                return false;
            mp[it]-=1;
            mp[it*2]-=1;
        }
        return true;
    }
};

class Solution(object):
    def canReorderDoubled(self, arr):
        """
        :type arr: List[int]
        :rtype: bool
        """
        cnt = collections.Counter(arr)
        if cnt[0] % 2 != 0:
            return False
        for k in sorted(cnt.keys(), key=lambda x: abs(x)):
            if cnt[k] > cnt[k * 2]:
                return False
            cnt[k * 2] -= cnt[k]
        return True
